public class Driver { static class OutOfStock extends Exception{final int shortfall;OutOfStock(String item,int s){super("Out of stock for "+item+" (short by "+s+")");shortfall=s;}}static class Warehouse{int stock=10;void issue(String item,int q)throws OutOfStock{if(q<=0)throw new IllegalArgumentException("Quantity must be > 0");if(q>stock)throw new OutOfStock(item,q-stock);stock-=q;System.out.println("Issued "+q+" of "+item+". Remaining: "+stock);}}public static void main(String[]a){Warehouse w=new Warehouse();for(int q:new int[]{4,-2,8,3})try{w.issue("Laptop",q);}catch(OutOfStock e){System.out.println("Stock Failure: "+e.getMessage()+" [Shortfall: "+e.shortfall+"]");}catch(IllegalArgumentException e){System.out.println("Invalid Request: "+e.getMessage());}}}
